/* This example demonstrates tee() duplicating data from Pipe A to Pipe B. 
 * The crucial aspect is that after tee() runs, the data is readable from both pipes.
 * Requires Linux (since tee is a Linux-specific syscall).
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <fcntl.h>

// Function defined in unistd.h via _GNU_SOURCE
extern ssize_t tee(int fd_in, int fd_out, size_t len, unsigned int flags);

int main() {
    int pipe_a[2]; // Pipe A: Input source
    int pipe_b[2]; // Pipe B: Output destination
    const char *test_data = "Hello Tee Call!";
    size_t data_len = strlen(test_data);
    ssize_t n_copied;
    char buffer_a[50] = {0};
    char buffer_b[50] = {0};

    if (pipe(pipe_a) == -1 || pipe(pipe_b) == -1) {
        perror("pipe initialization failed");
        return 1;
    }

    // 1. Write data to the write end of Pipe A
    if (write(pipe_a[1], test_data, data_len) != (ssize_t)data_len) {
        perror("write to pipe A failed");
        return 1;
    }

    // 2. Duplicate data from Pipe A (read end) to Pipe B (write end)
    // This does not consume the data from Pipe A.
    n_copied = tee(pipe_a[0], pipe_b[1], data_len, 0);

    if (n_copied < 0) {
        perror("tee failed");
        return 1;
    }

    printf("Successfully used tee to copy %zd bytes.\n", n_copied);

    // 3. Read data from Pipe B (the duplicate copy)
    if (read(pipe_b[0], buffer_b, data_len) != (ssize_t)data_len) {
        perror("read from pipe B failed");
        return 1;
    }
    printf("Pipe B (Destination): %s\n", buffer_b);

    // 4. Read data from Pipe A (the original source, proving it was not consumed)
    if (read(pipe_a[0], buffer_a, data_len) != (ssize_t)data_len) {
        perror("read from pipe A failed");
        return 1;
    }
    printf("Pipe A (Source):      %s\n", buffer_a);

    close(pipe_a[0]); close(pipe_a[1]);
    close(pipe_b[0]); close(pipe_b[1]);

    if (strcmp(buffer_a, test_data) == 0 && strcmp(buffer_b, test_data) == 0) {
        return 0;
    }
    return 1;
}
